INSERT INTO "public"."page_contents" ("id", "page_key", "content_key", "content_text", "updated_at") VALUES (1, 'societies', 'societies_hero_badge', 'IEEE SREC Technical Affiliations', '2026-08-18 11:37:57.504268+00'), (2, 'societies', 'societies_hero_title', 'Specialized Technical Societies & Chapters', '2026-08-18 11:37:57.504268+00'), (3, 'societies', 'societies_hero_subtitle', 'Explore SREC''s 8 specialized IEEE technical societies and student branch wings. Engage in global hackathons, cutting-edge research symposiums, industry certifications, and leadership roles.', '2026-08-18 11:37:57.504268+00'), (4, 'societies', 'societies_cta_badge', 'Join IEEE SREC Student Branch', '2026-08-18 11:37:57.504268+00'), (5, 'societies', 'societies_cta_title', 'Ready to Accelerate Your Engineering Career?', '2026-08-18 11:37:57.504268+00'), (6, 'societies', 'societies_cta_subtitle', 'Join 500+ student engineers at SREC. Get access to IEEE Xplore digital library, global society memberships, technical workshops, paper publications, and leadership credentials.', '2026-08-18 11:37:57.504268+00');